-- Target: guideSections (TR) - Published
UPDATE public.cms_localizations
SET
  payload = '[{"id":"registration","label":"Üniversite Kaydı","title":"Üniversite Kayıt Rehberi","intro":"Erzurum Atatürk Üniversitesi''ne kayıt için gerekli belgelerden online başvuru adımlarına kadar bilmeniz gereken her şey.","items":[{"id":"reg-1","heading":"Gerekli Belgeler","body":"Kayıt sürecine başlamadan önce aşağıdaki belgelerin hazır olduğundan emin olun:","tips":["Orijinal pasaport + noter onaylı fotokopisi","Türkçe veya İngilizceye tercüme edilmiş ve onaylanmış lise diploması","Güncel biyometrik fotoğraf (6 adet)","Not döküm belgesi (transkript - varsa)","Üniversite kabul mektubu (varsa)","Dil yeterlilik belgesi (TÖMER / YDS - varsa)"]},{"id":"reg-2","heading":"Online Kayıt Adımları","body":"Aşağıdaki adımları takip ederek üniversitenin online portalı üzerinden kayıt yapabilirsiniz:","tips":["Atatürk Üniversitesi web sitesine giriş: atauni.edu.tr","Kayıt sisteminde yeni öğrenci hesabı oluşturma","Kişisel ve akademik bilgileri eksiksiz doldurma","Gerekli belgeleri PDF formatında yükleme","Başvuruyu kontrol edip onaylama"]},{"id":"reg-3","heading":"Kayıt ve Harç Ücretleri","body":"Harçlar bölüme ve kabul türüne göre değişir. Uluslararası öğrenciler harç indirimlerinden faydalanabilir.","tips":[]}],"contacts":[{"id":"reg-c1","label":"Uluslararası Öğrenci İşleri Ofisi"},{"id":"reg-c2","label":"Kayıt Portalı Web Sitesi"}]},{"id":"housing","label":"Öğrenci Yurtları ve Konaklama","title":"Öğrenci Konaklama Rehberi","intro":"Erzurum''da devlet yurtlarından özel dairelere kadar öğrencilere sunulan barınma seçenekleri.","items":[{"id":"h-1","heading":"KYK Devlet Öğrenci Yurdu","body":"KYK merkezleri sübvansiyonlu fiyatlarla öğrenci yurdu sağlar. Kayıtlar her yıl resmi web sitesi üzerinden yapılır.","tips":["Konum: Yenişehir Mahallesi, Erzurum","Aylık ücret: yaklaşık 500-800 TL","Dahil olanlar: Yemek, internet, çamaşırhane","Başvuru: kyk.gov.tr"]},{"id":"h-2","heading":"Özel Kiralık Daireler","body":"Üniversite çevresinde eşyalı ve eşyasız daireler mevcuttur. Akademik yıl başlamadan önce erken arama yapılması önerilir.","tips":["1+1 daire aylık ortalama: 4.000 - 7.000 TL","2+1 daire aylık ortalama: 6.000 - 10.000 TL","Önerilen semtler: Yenişehir, Kazım Karabekir, Şehir Merkezi"]},{"id":"h-3","heading":"Aile Yanı Konaklama","body":"Bir Türk ailesinin yanında oda ve yemek içeren ekonomik bir seçenek. Sessiz bir ortam tercih edenler için idealdir.","tips":["Aylık ücret: 3.000 - 5.000 TL (yemek dahil)","Erzurum öğrenci sosyal medya gruplarından araştırılabilir"]}],"contacts":[{"id":"h-c1","label":"KYK Yurt Hizmetleri Merkezi"},{"id":"h-c2","label":"KYK Resmi Portalı"}]},{"id":"transport","label":"Şehir İçi Ulaşım","title":"Ulaşım Rehberi","intro":"Erzurum''da üniversite, yurtlar ve şehir merkezi arasında rahat ve uygun fiyatlı ulaşım rehberi.","items":[{"id":"t-1","heading":"Belediye Otobüsleri","body":"Belediye otobüsleri şehrin büyük kısmına tek fiyatlı ekonomik biletlerle ulaşım sağlar.","tips":["Bilet ücreti: İndirimli öğrenci tarifesi","Ödemeler ErzurumKart ile yapılır","1 ve 3 numaralı hatlar doğrudan kampüse gider","Çalışma saatleri: 06:00 - 23:30"]},{"id":"t-2","heading":"Toplu Taşıma Hatları","body":"Şehir merkezi ile otogar arasında öğrenci yoğunluklu güzergahlardan geçen minibüs ve servis hatları mevcuttur.","tips":["Ana duraklar: Aziziye, Kazım Karabekir, Üniversite Kampüsü","Uygun fiyatlı öğrenci tarifesi","Seferler: 06:00 - 24:00"]},{"id":"t-3","heading":"Taksi Hizmetleri","body":"Şehir genelinde taksi durakları mevcuttur. Daha kolay ulaşım için taksi mobil uygulamaları tercih edilebilir.","tips":["BiTaksi uygulaması Erzurum''da aktiftir"]}],"contacts":[{"id":"t-c1","label":"Belediye Ulaşım Destek Hattı"},{"id":"t-c2","label":"BiTaksi Uygulama Bağlantısı"}]},{"id":"libraries","label":"Kütüphaneler ve Akademik Hizmetler","title":"Kütüphane ve Akademik Hizmetler","intro":"Atatürk Üniversitesi''nde öğrencilerin erişimine açık kütüphaneler, çalışma salonları ve dijital kaynaklar.","items":[{"id":"lib-1","heading":"Atatürk Üniversitesi Merkez Kütüphanesi","body":"Türkçe, İngilizce ve Arapça dillerinde binlerce kitap ve kaynak barındıran modern kütüphane.","tips":["Konum: Ana Üniversite Kampüsü içinde","Çalışma saatleri: 08:00 - 24:00 (Sınav dönemlerinde 7/24)","Kayıtlı öğrenciler için ücretsiz ödünç kitap hizmeti","Ücretsiz Wi-Fi ve sessiz çalışma salonları"]},{"id":"lib-2","heading":"Elektronik Veri Tabanları","body":"Üniversite, öğrenci hesabı üzerinden uluslararası akademik veri tabanlarına ücretsiz erişim sağlar.","tips":["EBSCO, Scopus, Web of Science","JSTOR, ScienceDirect","Erişim: kutuphane.atauni.edu.tr"]},{"id":"lib-3","heading":"Akademik Destek Merkezi","body":"Zorlandıkları derslerde öğrencilere etütler, bireysel danışmanlık ve takviye kursları sunar.","tips":["Matematik, fizik ve yabancı dil için ücretsiz destek","Bireysel akademik danışmanlık görüşmeleri"]}],"contacts":[{"id":"lib-c1","label":"Merkez Kütüphane Danışma"},{"id":"lib-c2","label":"Dijital Kütüphane Portalı"}]},{"id":"sec1787646993609","label":"Alışveriş ve Yaşam","title":"Erzurum''da Alışveriş ve Günlük Yaşam","intro":"Erzurum''da öğrencilerin ihtiyaç duyduğu mağazalar, çarşılar ve yaşam alanları rehberi.","items":[{"id":"item1787647011505","heading":"Alışveriş Merkezleri ve Çarşılar","body":"Kampüse yakın alışveriş merkezleri ve tarihi çarşılar.","tips":["MNG Alışveriş Merkezi","Tarihi Taşhan Çarşısı","Cumhuriyet Caddesi öğrenci mağazaları"]}],"contacts":[]}]'::jsonb,
