-- Target: guideSections (EN) - Published
UPDATE public.cms_localizations
SET
  payload = '[{"id":"registration","label":"University Enrollment","title":"University Enrollment Guide","intro":"Everything you need to know about registering at Ataturk University in Erzurum, from required documents to online portal steps.","items":[{"id":"reg-1","heading":"Required Documents","body":"Ensure you have the following documents ready before starting registration:","tips":["Original passport + notarized copy","High school diploma certified and translated into Turkish or English","Recent biometric photos (6 photos)","Academic transcripts (if available)","University acceptance letter (if available)","Language proficiency certificate (TOMER / YDS, if available)"]},{"id":"reg-2","heading":"Online Registration Steps","body":"Register through the university student portal following these steps:","tips":["Visit the Ataturk University portal: atauni.edu.tr","Create a new student account in the registration system","Fill in personal and academic details accurately","Upload required documents in PDF format","Review and submit the application"]},{"id":"reg-3","heading":"Tuition and Fees","body":"Tuition fees vary by department and admission type. International students may qualify for fee reductions.","tips":[]}],"contacts":[{"id":"reg-c1","label":"International Student Affairs Office"},{"id":"reg-c2","label":"Registration Portal"}]},{"id":"housing","label":"Student Housing","title":"Student Housing Guide","intro":"Housing options available for students in Erzurum, from government dormitories to private apartments.","items":[{"id":"h-1","heading":"Government Student Dormitories (KYK)","body":"KYK centers provide subsidized student housing. Registration takes place annually via the official portal.","tips":["Location: Yenisehir District, Erzurum","Monthly fees: approx. 500-800 TRY","Includes: Meals, Wi-Fi, laundry facilities","Application: kyk.gov.tr"]},{"id":"h-2","heading":"Private Rental Apartments","body":"Furnished and unfurnished apartments are available near the campus. Early search before the semester is advised.","tips":["Monthly average for 1+1: 4,000 - 7,000 TRY","Monthly average for 2+1: 6,000 - 10,000 TRY","Recommended areas: Yenisehir, Kazim Karabekir, City Center"]},{"id":"h-3","heading":"Homestay Living","body":"An economical option staying with a local family including private room and meals. Ideal for quiet study environments.","tips":["Monthly cost: 3,000 - 5,000 TRY (meals included)","Can be arranged through local student networks in Erzurum"]}],"contacts":[{"id":"h-c1","label":"KYK Student Housing Center"},{"id":"h-c2","label":"KYK Portal"}]},{"id":"transport","label":"City Transportation","title":"Transportation Guide","intro":"Navigating Erzurum between university, residences, and vibrant city spots.","items":[{"id":"t-1","heading":"Municipal Buses","body":"Municipal buses cover most areas of the city with unified discounted student fares.","tips":["Discounted student fares","Payment is made with ErzurumKart","Routes 1 and 3 run directly to campus","Operating hours: 6:00 AM - 11:30 PM"]},{"id":"t-2","heading":"Transit Routes","body":"Transit minibuses connect city center and bus terminals through major student neighborhoods.","tips":["Major stops: Aziziye, Kazim Karabekir, University Campus","Affordable student rates","Operating hours: 6:00 AM - 12:00 Midnight"]},{"id":"t-3","heading":"Taxi Services","body":"Taxis are available throughout the city. Ride-hailing apps provide reliable rates.","tips":["BiTaksi app is available in Erzurum"]}],"contacts":[{"id":"t-c1","label":"Municipal Transit Authority"},{"id":"t-c2","label":"BiTaksi App"}]},{"id":"libraries","label":"Libraries & Academic Services","title":"Libraries & Academic Services","intro":"Libraries, study centers, and academic support services available to students at Ataturk University.","items":[{"id":"lib-1","heading":"Ataturk University Central Library","body":"A comprehensive modern library housing thousands of books and references in Turkish, English, and Arabic.","tips":["Location: Inside the Main University Campus","Operating hours: 8:00 AM - 12:00 Midnight (24/7 during exam periods)","Free book borrowing service for registered students","Free Wi-Fi and quiet study rooms"]},{"id":"lib-2","heading":"Electronic Databases","body":"The university provides free access to global academic research databases through student accounts.","tips":["EBSCO, Scopus, Web of Science","JSTOR, ScienceDirect","Access: kutuphane.atauni.edu.tr"]},{"id":"lib-3","heading":"Academic Support Center","body":"Offers study support, tutoring, and remedial sessions for students facing academic challenges.","tips":["Free tutoring in mathematics, physics, and languages","One-on-one academic counseling sessions"]}],"contacts":[{"id":"lib-c1","label":"Central Library Information Desk"},{"id":"lib-c2","label":"Digital Library Portal"}]},{"id":"sec1787646993609","label":"Shopping & Daily Life","title":"Shopping & Living in Erzurum","intro":"Guide to local markets, shopping malls, and daily living amenities in Erzurum.","items":[{"id":"item1787647011505","heading":"Shopping Malls & Bazaars","body":"Popular local markets and shopping centers located close to campus.","tips":["MNG Shopping Mall","Historic Tashan Bazaar","Student shops along Cumhuriyet Street"]}],"contacts":[]}]'::jsonb,
  source_hash = 'b5e789c5',
  status = 'fresh',
  manual_paths = ARRAY['*']::text[],
  stale_paths = ARRAY[]::text[],
  source_version = 1,
  updated_at = '2026-09-07T00:00:00.000Z'
WHERE target = 'guideSections'
  AND locale = 'en'
  AND partition = 'published';

